end

exec('set_trf_data_profile profile_id=1 trf_id=1 period_ms=100 size=1350 burst=60 seconds=600 protocol=tcp') --heavy user DL
exec('set_trf_data_profile profile_id=2 trf_id=1 period_ms=100 size=1350 burst=10 seconds=600 protocol=tcp') --heavy user UL
exec('set_trf_data_profile profile_id=3 trf_id=1 period_ms=3000 size=1350 burst=30 seconds=600 protocol=tcp') --medium user DL
exec('set_trf_data_profile profile_id=4 trf_id=1 period_ms=3000 size=1350 burst=3 seconds=600 protocol=tcp') --medium user UL
exec('set_trf_data_profile profile_id=5 trf_id=1 period_ms=6000 size=1000 burst=15 seconds=600 protocol=tcp') --light user DL
exec('set_trf_data_profile profile_id=6 trf_id=1 period_ms=6000 size=200 burst=15 seconds=600 protocol=tcp') --light user UL
exec('set_trf_data_profile profile_id=7 rtp_codec=amr_12_2') -- VoNR user

